class LLMProviderType(enum.Enum):
    OLLAMA = "ollama"
    OPENAI = "openai"
    ANTHROPIC = "anthropic"
    GEMINI = "gemini"

class LLMResponse(BaseModel):
    content: str
    # Future: Add token usage, cost, finish reason, etc.

class LLMProvider(ABC):
    """Abstract base class for all LLM providers."""

    def __init__(self, model: str):
        self.model = model

    @abstractmethod
    def _invoke_internal(self, prompt: str, system_prompt: str) -> str:
        """Internal method to call the specific LLM API."""
        pass

    def invoke(self, prompt: str, system_prompt: str, max_retries: int = 3, initial_delay: float = 1.0) -> LLMResponse:
        """
        Invokes the LLM with retry logic.
        Ensures standard urllib HTTP transport with automated retry backoff.
        """
        for attempt in range(max_retries):
            try:
                content = self._invoke_internal(prompt, system_prompt)
                return LLMResponse(content=content)
            except (APIConnectionError, RateLimitError, AnthropicAPIConnectionError, AnthropicRateLimitError,
                    ResourceExhausted, ServiceUnavailable, ollama.ResponseError) as e:
                if attempt < max_retries - 1:
                    delay = initial_delay * (2 ** attempt) # Exponential backoff
                    print(f"Attempt {attempt + 1} failed with {type(e).__name__}. Retrying in {delay:.2f} seconds...")
                    time.sleep(delay)
                else:
                    print(f"All {max_retries} attempts failed. Last error: {e}")
                    raise # Re-raise the last exception if all retries fail
            except Exception as e:
                # Catch any other unexpected errors immediately
                print(f"An unexpected error occurred: {e}")
                raise

class OllamaProvider(LLMProvider):
    def __init__(self, model: str = "llama3:8b"):
        if ollama is None:
            raise ImportError("Ollama library not installed. Please install it with 'pip install ollama'.")
        super().__init__(model)
        self.client = ollama.Client()

    def _invoke_internal(self, prompt: str, system_prompt: str) -> str:
        response = self.client.chat(
            model=self.model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": prompt},
            ],
        )
        return response["message"]["content"]

class OpenAIProvider(LLMProvider):
    def __init__(self, model: str = "gpt-4o-mini"):
        if OpenAI is None:
            raise ImportError("OpenAI library not installed. Please install it with 'pip install openai'.")
        super().__init__(model)
        api_key = os.getenv("OPENAI_API_KEY")
        if not api_key:
            raise ValueError("OPENAI_API_KEY environment variable not set.")
        self.client = OpenAI(api_key=api_key)

    def _invoke_internal(self, prompt: str, system_prompt: str) -> str:
        response = self.client.chat.completions.create(
            model=self.model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": prompt},
            ],
        )
        return response.choices[0].message.content

class AnthropicProvider(LLMProvider):
    def __init__(self, model: str = "claude-3-5-sonnet-20240620"):
        if Anthropic is None:
            raise ImportError("Anthropic library not installed. Please install it with 'pip install anthropic'.")
        super().__init__(model)
        api_key = os.getenv("ANTHROPIC_API_KEY")
        if not api_key:
            raise ValueError("ANTHROPIC_API_KEY environment variable not set.")
        self.client = Anthropic(api_key=api_key)

    def _invoke_internal(self, prompt: str, system_prompt: str) -> str:
        response = self.client.messages.create(
            model=self.model,
            max_tokens=4096, # Anthropic requires max_tokens
            system=system_prompt,
            messages=[
                {"role": "user", "content": prompt},
            ],
        )
        return response.content[0].text

class GeminiProvider(LLMProvider):
    def __init__(self, model: str = "gemini-pro"):
        if genai is None:
            raise ImportError("Google Generative AI library not installed. Please install it with 'pip install google-generativeai'.")
        super().__init__(model)
        api_key = os.getenv("GOOGLE_API_KEY")
        if not api_key:
            raise ValueError("GOOGLE_API_KEY environment variable not set.")
        genai.configure(api_key=api_key)
        self.client = genai.GenerativeModel(model_name=self.model)

    def _invoke_internal(self, prompt: str, system_prompt: str) -> str:
        # Gemini's generate_content takes system_instruction directly
        response = self.client.generate_content(
            contents=[
                {"role": "user", "parts": [prompt]},
            ],
            system_instruction=system_prompt,
        )
        return response.text


def get_llm_provider(provider_type: LLMProviderType, model: Optional[str] = None) -> LLMProvider:
    """Factory function for LLM providers."""
    provider_map = {
        LLMProviderType.OLLAMA: OllamaProvider,
        LLMProviderType.OPENAI: OpenAIProvider,
        LLMProviderType.ANTHROPIC: AnthropicProvider,
        LLMProviderType.GEMINI: GeminiProvider,
    }
    provider_class = provider_map.get(provider_type)
    if not provider_class:
        raise ValueError(f"Unsupported LLM provider: {provider_type}")

    # Instantiate with model if provided, otherwise use default
    return provider_class(model=model) if model else provider_class()

