        self.model = model

    def invoke(self, prompt: str, system_prompt: str) -> LLMResponse:
        # Gemini's system instruction can be set at model creation or prepended.
        # For consistency with other providers, we'll prepend if not set at model init.
        # However, the genai.GenerativeModel can take `system_instruction` directly.
