import yaml
import os
from pathlib import Path
from pydantic import BaseModel, Field, ValidationError
from typing import List, Dict, Optional

from .llm_provider import get_llm_provider, LLMProviderType, LLMResponse

class AgentConfig(BaseModel):
    role: str
    provider: LLMProviderType # Pydantic will automatically convert string to enum
    model: str
    system_prompt: str
    # Future: Add toolset, memory configuration, etc.

class OrgGenome(BaseModel):
    name: str
    topology: str # e.g., "pipeline", "broadcast", "hierarchical"
    agents: List[AgentConfig]

class Agent:
    def __init__(self, config: AgentConfig):
        self.config = config
        self.provider = get_llm_provider(config.provider, config.model)

    def execute(self, prompt: str) -> str:
        print(f"Agent '{self.config.role}' executing with model '{self.config.model}' via {self.config.provider.value}...")
        response = self.provider.invoke(prompt, self.config.system_prompt)
        return response.content

class Organization:
    def __init__(self, genome_path: Path):
        if not genome_path.exists():
            raise FileNotFoundError(f"Genome file not found at {genome_path}")

        with open(genome_path, 'r') as f:
            genome_data = yaml.safe_load(f)

        try:
            self.genome = OrgGenome(**genome_data)
        except ValidationError as e:
            print(f"Error validating genome file {genome_path}: {e}")
            raise

        self.agents: Dict[str, Agent] = {}
        for agent_config in self.genome.agents:
            try:
                self.agents[agent_config.role] = Agent(agent_config)
            except (ValueError, ImportError) as e:
                print(f"Warning: Could not initialize agent '{agent_config.role}' ({agent_config.provider.value}/{agent_config.model}): {e}")
                print(f"This agent will not be available in the organization.")
                # Optionally, you might want to raise an error here if an agent is critical
                # For now, we'll just skip it and log a warning.

        if not self.agents:
            raise RuntimeError("No agents successfully initialized in the organization. Check genome configuration and environment variables.")

        print(f"Organization '{self.genome.name}' instantiated with {len(self.agents)} active agents.")

    def delegate(self, role: str, prompt: str) -> str:
        if role not in self.agents:
            raise ValueError(f"No active agent with role '{role}' found in organization.")
        return self.agents[role].execute(prompt)

